"""Complete licensed violin score, octave-down audition; no modern guitar arrangement."""
import argparse,hashlib,json,subprocess,tempfile
from pathlib import Path
from import_bwv1012 import read_notes
from import_repertoire_batch4 import VOICE_MIDI
ROOT=Path(__file__).resolve().parents[1];SOURCES=ROOT/'scripts/score-sources/bwv1004-chaconne'
def compile_midi(executable):
 with tempfile.TemporaryDirectory() as directory:
  text=subprocess.run([str(Path(executable).with_name('convert-ly')),str(SOURCES/'bwv-1004_5.ly')],capture_output=True,text=True,check=True).stdout
  text=text.replace('\\midi {','\\midi { '+VOICE_MIDI)
  for name,voice in [('chaconne',None),('voice1','melodyOne'),('voice2','melodyTwo'),('voice3','melodyThree'),('voice4','melodyFour')]:
   music=text if voice is None else text.replace('\\partial 2 \\melody  }','\\partial 2 \\'+voice+'  }')
   f=Path(directory)/(name+'.ly');f.write_text(music)
   subprocess.run([executable,'-dno-print-pages','-dbackend=null','-o',str(SOURCES/name),str(f)],check=True)
def build():
 raw=read_notes((SOURCES/'chaconne.midi').read_bytes());assert len(raw)==3123
 voices=[]
 for i in range(1,5):
  e=read_notes((SOURCES/f'voice{i}.midi').read_bytes())
  # Reader removes the first-note offset. Voice3 explicitly starts with s2.
  voices.extend([[a+(2 if i==3 else 0),p,d] for a,p,d in e])
 assert sorted(voices)==raw,'All four independent voices must survive merged MIDI'
 events=[[a,p-12,d] for a,p,d in raw];assert max(a+d for a,p,d in events)==770
 source=dict(credit='J. S. Bach / violin engraving Hajo Dezelski / Mutopia (2019); BGA 1879 vol.27.1',url='https://www.mutopiaproject.org/cgibin/piece-info.cgi?id=1426',license='CC BY-SA 3.0',licenseUrl='https://creativecommons.org/licenses/by-sa/3.0/',modifications='Complete edition, no repeat signs. convert-ly/LilyPond2.24.4, four separate MIDI voices; all3123 notes/holds/unisons retained. Entire violin sounding score shifted -12 semitones. Written running figures retained; arpeggio text at source bars89/201 is NOT realized: sustained/simultaneous chords remain literal. No Segovia arrangement/bass additions. Fixed audition quarter=60; source has no tempo. Trill/fermata not realized; app articulation separate.',pitch='D minor/D major/D minor retained. Violin G3-G6 (55-91) -> G2-G5 (43-79), -12 semitones intentional transposition, NOT guitar notation correction. Standard6-string range; held-string assignment passes, conservative fret-span4 fails at beat491.5 (two A3 voices). Fingers/barres/hand motion unverified; no automatic tuning changes.',terms='Derived score data CC BY-SA3.0; retain attribution, license and changes; share adaptations under the same license. Application code separate.',endingStatus='版の2拍アウフタクト＋256個の3拍区間＝770拍。最後の同音2声767–770拍を保持。アルペジオ指示未展開。')
 assert all(len(v)<=500 for v in source.values())
 title='J. S. Bach · BWV 1004 — Chaconne'
 songs={'chaconne1004':dict(score=dict(title=title,bpm=60,meter=[3,4],endBeat=770,events=events),label=title,option='Chaconne（シャコンヌ）',edition='全曲・原ヴァイオリン譜−1oct・アルペジオ指示未展開・運指未検証',source=source)}
 (ROOT/'synth-demo/bwv1004-chaconne.js').write_text('// Generated by scripts/import_bwv1004_chaconne.py. Score data CC BY-SA3.0, Hajo Dezelski; source metadata below.\nconst bwv1004Chaconne = '+json.dumps(songs,ensure_ascii=False,separators=(',',':')).replace('],[','],\n[')+';\n')
 files=['bwv-1004_5.ly','chaconne.midi']+[f'voice{i}.midi' for i in range(1,5)]
 manifest=dict(key='chaconne1004',source=source,notes=len(events),endBeat=770,noteEndBeat=770,meter=[3,4],bpm=60,pitchShift=-12,pitchRange=[43,79],rawPitchRange=[55,91],rawVoiceCounts=[len(read_notes((SOURCES/f'voice{i}.midi').read_bytes())) for i in range(1,5)],structure='2-beat opening plus256 full3-beat segments, source comments1..257; no added fermata or silence',keyChangeBeats=[395,623],arpeggioTextBeats=[264,599],sourceUrl='https://raw.githubusercontent.com/MutopiaProject/MutopiaProject/master/ftp/BachJS/BWV1004/bwv-1004_5/bwv-1004_5.ly',sha256={f:hashlib.sha256((SOURCES/f).read_bytes()).hexdigest() for f in files})
 (SOURCES/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n');print('Built',manifest['notes'],manifest['rawVoiceCounts'],manifest['pitchRange'],manifest['endBeat'])
if __name__=='__main__':
 parser=argparse.ArgumentParser();parser.add_argument('--lilypond');args=parser.parse_args()
 if args.lilypond:compile_midi(args.lilypond)
 build()
